async function snapshot() {
  return {
    members: (await sql.query('SELECT * FROM team_members ORDER BY id')).rows,
    invitations: (await sql.query('SELECT * FROM invitations ORDER BY id')).rows,
    activity: (await sql.query('SELECT * FROM activity_logs ORDER BY id')).rows
  };
}

function remove(value: string | Blob | null) {
  const form = new FormData();
  if (value !== null) form.set('memberId', value);
  return actions.removeTeamMember({}, form);
}

function invite(email = 'new@fixture.invalid', role = 'member') {
  const form = new FormData();
  form.set('email', email);
  form.set('role', role);
  return actions.inviteTeamMember({}, form);
}

async function markup() {
  const user = await queries.getUser();
  const team = await queries.getTeamForUser();
  return renderToStaticMarkup(
    <SWRConfig value={{
      provider: () => new Map(),
      fallback: { '/api/user': user, '/api/team': team },
      revalidateOnMount: false
    }}>
      <Page />
    </SWRConfig>
  );
}

describe('team permission boundary regressions', () => {
  it.each([null, '', ' ', '0', '-1', '2.5', '2garbage', '2e0', '0x2', 'NaN', 'Infinity', '2147483648', '9007199254740993'])(
    'rejects invalid FormData memberId %j without changing SQL or activity',
    async (value) => {
      const before = await snapshot();
      expect(await remove(value)).toHaveProperty('error');
      expect(await snapshot()).toEqual(before);
    }
  );

  it('rejects a file as memberId without changing SQL or activity', async () => {
    const before = await snapshot();
    expect(await remove(new Blob(['2']))).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it.each(['3', '999'])('rejects a foreign or absent member %s without a success log', async (id) => {
    const before = await snapshot();
    expect(await remove(id)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('removes the second listed member once and preserves their other team membership', async () => {
    expect(await remove('2')).toHaveProperty('success');
    expect((await sql.query('SELECT id, team_id FROM team_members WHERE user_id=2')).rows)
      .toEqual([{ id: 4, team_id: 2 }]);
    expect((await sql.query('SELECT team_id, user_id, action FROM activity_logs')).rows)
      .toEqual([{ team_id: 1, user_id: 1, action: 'REMOVE_TEAM_MEMBER' }]);
    const afterRemoval = await snapshot();
    expect(await remove('2')).toHaveProperty('error');
    expect(await snapshot()).toEqual(afterRemoval);
  });

  it('keeps both team selectors on the same membership after a row update', async () => {
    await login(2);
    await sql.exec("UPDATE team_members SET joined_at=CURRENT_TIMESTAMP WHERE id=2");
    expect(await queries.getUserWithTeam(2)).toMatchObject({ teamId: 1, teamRole: 'member' });
    expect(await (await GET()).json()).toMatchObject({ id: 1 });
    const before = await snapshot();
    expect(await invite()).toHaveProperty('error');
    // Even targeting their other team does not grant current-team management.
    expect(await remove('3')).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('does not trust a submitted owner role or team ID for authorization', async () => {
    await login(2);
    const form = new FormData();
    form.set('email', 'new@fixture.invalid');
    form.set('role', 'owner');
    form.set('teamId', '2');
    form.set('teamRole', 'owner');
    form.set('memberId', '3');
    const before = await snapshot();
    expect(await actions.inviteTeamMember({}, form)).toHaveProperty('error');
    expect(await actions.removeTeamMember({}, form)).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('checks the latest database role after ownership is revoked', async () => {
    await sql.exec("UPDATE team_members SET role='member' WHERE id=1");
    const before = await snapshot();
    expect(await invite()).toHaveProperty('error');
    expect(await remove('2')).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('denies a global owner without any team and returns no roster', async () => {
    await login(4);
    const before = await snapshot();
    expect(await (await GET()).json()).toBeNull();
    expect(await invite()).toHaveProperty('error');
    expect(await remove('2')).toHaveProperty('error');
    expect(await snapshot()).toEqual(before);
  });

  it('rejects unauthenticated removal without any writes', async () => {
    request.token = '';
    const before = await snapshot();
    await expect(remove('2')).rejects.toThrow();
    expect(await snapshot()).toEqual(before);
  });

  it('preserves owner invitation roles, current team, and duplicate protection', async () => {
    expect(await invite('new@fixture.invalid', 'owner')).toHaveProperty('success');
    expect((await sql.query('SELECT team_id, invited_by, role, status FROM invitations')).rows)
      .toEqual([{ team_id: 1, invited_by: 1, role: 'owner', status: 'pending' }]);
    expect((await sql.query('SELECT team_id, user_id, action FROM activity_logs')).rows)
      .toEqual([{ team_id: 1, user_id: 1, action: 'INVITE_TEAM_MEMBER' }]);
    const afterInvite = await snapshot();
    expect(await invite()).toHaveProperty('error');
    expect(await invite('member@fixture.invalid')).toHaveProperty('error');
    expect(await snapshot()).toEqual(afterInvite);
  });

  it('enables removal for an owner with only two listed members', async () => {
    const html = await markup();
    const memberForm = html.match(/<form\b[^>]*>(?:(?!<\/form>)[\s\S])*name="memberId"[^>]*value="2"(?:(?!<\/form>)[\s\S])*<\/form>/)?.[0];
    expect(memberForm).toBeDefined();
    expect(memberForm).toContain('Remove');
    expect(memberForm).not.toMatch(/\bdisabled(?:=|\s|>)/);
  });

  it('disables every management control for members and explains both restrictions', async () => {
    await login(2);
    const html = await markup();
    const removeButtons = [...html.matchAll(/<button\b([^>]*)>Remove<\/button>/g)];
    expect(removeButtons).toHaveLength(2);
    expect(removeButtons.every((button) => /\bdisabled(?:=|\s|$)/.test(button[1]))).toBe(true);
    const radios = [...html.matchAll(/<button\b(?=[^>]*role="radio")([^>]*)>/g)];
    expect(radios).toHaveLength(2);
    expect(radios.every((radio) => /\bdisabled(?:=|\s|$)/.test(radio[1]))).toBe(true);
    expect(html).toContain('id="remove-permission"');
    expect(html).toContain('id="invite-permission"');
    expect(html).toContain('Only a team owner can invite or remove team members.');
    expect(html).toContain('Member');
  });
});

